use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut result = Vec::new();
    if arr.len() == 0 {
        return Value::Array(vec![]);
    }
    for i in 1..arr.len() {
        result.push(Value::from(arr[i] - arr[i - 1]));
    }
    Value::Array(result)
}
